import { test } from 'node:test';
import { strict as assert } from 'node:assert';
import { exportCsv } from '../src/export.js';

test('exportCsv - empty invoices array', () => {
  const csv = exportCsv([]);
  const lines = csv.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines.length, 2); // header + final newline creates empty last line
});

test('exportCsv - single issued invoice', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[0], 'number,customer,issueDate,dueDate,status,subtotal,discount,vat,total,due');
  assert.equal(lines[1], 'INV-001,ACME Corporation,2026-10-01,2026-10-31,issued,100.00,0.00,0.00,100.00,100.00');
});

test('exportCsv - draft invoice without number', () => {
  const invoices = [
    {
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'draft',
      terms: 'NET30',
      lines: [{ qty: 1, unitPrice: 5000, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], ',ACME Corporation,2026-10-01,2026-10-31,draft,50.00,0.00,0.00,50.00,50.00');
});

test('exportCsv - invoice with VAT', () => {
  const invoices = [
    {
      number: 'INV-002',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 19 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-002,ACME Corporation,2026-10-01,2026-10-31,issued,100.00,0.00,19.00,119.00,119.00');
});

test('exportCsv - invoice with discount', () => {
  const invoices = [
    {
      number: 'INV-003',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 10, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-003,ACME Corporation,2026-10-01,2026-10-31,issued,100.00,10.00,0.00,90.00,90.00');
});

test('exportCsv - multiple invoices', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 5000, discountPercent: 0, vatRate: 0 }],
    },
    {
      number: 'INV-002',
      customerId: 'ACME',
      issueDate: '2026-10-02',
      dueDate: '2026-11-01',
      status: 'issued',
      lines: [{ qty: 2, unitPrice: 2500, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines.length, 3); // header + 2 invoices + final newline
  assert.equal(lines[1], 'INV-001,ACME Corporation,2026-10-01,2026-10-31,issued,50.00,0.00,0.00,50.00,50.00');
  assert.equal(lines[2], 'INV-002,ACME Corporation,2026-10-02,2026-11-01,issued,50.00,0.00,0.00,50.00,50.00');
});

test('exportCsv - with payment reduces due', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'partially_paid',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 3000, date: '2026-10-10' }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-001,ACME Corporation,2026-10-01,2026-10-31,partially_paid,100.00,0.00,0.00,100.00,70.00');
});

test('exportCsv - customer name with comma', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ABC123',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 5000, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-001,"Smith, John",2026-10-01,2026-10-31,issued,50.00,0.00,0.00,50.00,50.00');
});

test('exportCsv - customer name with double quote', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'XYZ789',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 5000, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-001,"Joe\'s ""Special"" Shop",2026-10-01,2026-10-31,issued,50.00,0.00,0.00,50.00,50.00');
});

test('exportCsv - line endings', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 5000, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  assert.ok(csv.endsWith('\n'));
  const lines = csv.split('\n');
  assert.equal(lines[lines.length - 1], '');
});

test('exportCsv - amount formatting with decimals', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 12345, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-001,ACME Corporation,2026-10-01,2026-10-31,issued,123.45,0.00,0.00,123.45,123.45');
});

test('exportCsv - small amounts', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 5, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-001,ACME Corporation,2026-10-01,2026-10-31,issued,0.05,0.00,0.00,0.05,0.05');
});

test('exportCsv - multiple lines with VAT and discount', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [
        { qty: 1, unitPrice: 10000, discountPercent: 5, vatRate: 19 },
        { qty: 2, unitPrice: 5000, discountPercent: 0, vatRate: 7 },
      ],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  // Subtotal: 100 + 100 = 200
  // Discount: 5 + 0 = 5
  // VAT: (95 * 0.19) + (100 * 0.07) = 18.05 + 7 = 25.05
  // Total: 200 - 5 + 25.05 = 220.05
  assert.equal(lines[1], 'INV-001,ACME Corporation,2026-10-01,2026-10-31,issued,200.00,5.00,25.05,220.05,220.05');
});

test('exportCsv - paid invoice', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'paid',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
      payments: [{ amount: 10000, date: '2026-10-15' }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-001,ACME Corporation,2026-10-01,2026-10-31,paid,100.00,0.00,0.00,100.00,0.00');
});

test('exportCsv - no thousands separator', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 123456789, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  const lines = csv.split('\n');
  assert.equal(lines[1], 'INV-001,ACME Corporation,2026-10-01,2026-10-31,issued,1234567.89,0.00,0.00,1234567.89,1234567.89');
});

test('exportCsv - no currency symbol', () => {
  const invoices = [
    {
      number: 'INV-001',
      customerId: 'ACME',
      issueDate: '2026-10-01',
      dueDate: '2026-10-31',
      status: 'issued',
      lines: [{ qty: 1, unitPrice: 10000, discountPercent: 0, vatRate: 0 }],
    },
  ];

  const csv = exportCsv(invoices);
  assert.ok(!csv.includes('€'));
});

